if (element.querySelector('.pin-info-always-visible')) return;

var ariaLabel = element.getAttribute('aria-label') || '';
if (!ariaLabel || ariaLabel === 'Pin card') return;

var pinLink = element.querySelector('[data-test-id="deeplink-wrapper"] a');
if (!pinLink) return;
var title = pinLink.getAttribute('aria-label') || '';
if (!title || title === 'Pin' || title === 'Pin card') return;

var infoContainer = document.createElement('div');
infoContainer.className = 'pin-info-always-visible';
infoContainer.style.cssText = 'padding: 8px 4px; font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;';

var titleEl = document.createElement('div');
titleEl.style.cssText = 'font-size: 12px; font-weight: 600; color: #111; line-height: 1.3; margin-bottom: 4px; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; text-overflow: ellipsis;';
titleEl.textContent = title;

infoContainer.appendChild(titleEl);

element.appendChild(infoContainer);
